<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import AppOverlay from './AppOverlay.vue'
import { cardArtUrl } from '../cards/cardArt'
import { CARDS, cardsBySpeed, cardsByType, type CardInfo } from '../cards/cardData'

/**
 * 图鉴 / 卡库（spec 用户故事 14），没有新增路由。
 *
 * The legacy stack had a full collection screen; the frozen 11-route contract
 * has no slot for it, so it is an overlay opened from the home/settings screens.
 * The rows come from the build-time copy of the backend card table
 * (src/cards/card_data.json, regenerated by scripts/sync-card-data.mjs), and the
 * faces are the same content-hashed webp assets the hand uses.
 *
 * Rendering is progressive (PAGE_SIZE cards per batch) because the overlay must
 * stay responsive while the game bundle carries 48 faces; the "load more" button
 * keeps the gate deterministic (an IntersectionObserver alone could leave a
 * headless browser waiting forever).
 */
const props = defineProps<{ returnFocus?: () => HTMLElement | null }>()

const emit = defineEmits<{ (event: 'close'): void }>()

type Mode = 'speed' | 'type'
interface Group {
  key: string
  label: string
  total: number
  cards: CardInfo[]
}

const PAGE_SIZE = 18

const mode = ref<Mode>('speed')
const query = ref('')
const limit = ref(PAGE_SIZE)

const matches = (card: CardInfo, needle: string): boolean => {
  if (!needle) return true
  return (
    card.name.toLowerCase().includes(needle) ||
    card.type.toLowerCase().includes(needle) ||
    card.description.toLowerCase().includes(needle)
  )
}

const sourceGroups = computed<Group[]>(() => {
  const needle = query.value.trim().toLowerCase()
  if (mode.value === 'speed') {
    return cardsBySpeed()
      .map((group) => ({
        key: 'speed-' + group.speed,
        label: group.label,
        cards: group.cards.filter((card) => matches(card, needle)),
      }))
      .filter((group) => group.cards.length > 0)
      .map((group) => ({ ...group, total: group.cards.length }))
  }
  return cardsByType()
    .map((group) => ({
      key: 'type-' + group.type,
      label: group.type + ' 类',
      cards: group.cards.filter((card) => matches(card, needle)),
    }))
    .filter((group) => group.cards.length > 0)
    .map((group) => ({ ...group, total: group.cards.length }))
})

const total = computed(() => sourceGroups.value.reduce((sum, group) => sum + group.total, 0))

const visibleGroups = computed<Group[]>(() => {
  let budget = limit.value
  const rows: Group[] = []
  for (const group of sourceGroups.value) {
    if (budget <= 0) break
    const cards = group.cards.slice(0, budget)
    if (!cards.length) continue
    rows.push({ ...group, cards })
    budget -= cards.length
  }
  return rows
})

const shown = computed(() => visibleGroups.value.reduce((sum, group) => sum + group.cards.length, 0))
const hasMore = computed(() => shown.value < total.value)
const empty = computed(() => total.value === 0)

watch([mode, query], () => {
  limit.value = PAGE_SIZE
})

function loadMore(): void {
  limit.value += PAGE_SIZE
}

function faceFor(card: CardInfo): string | null {
  return cardArtUrl(card.name)
}

function close(): void {
  emit('close')
}
</script>

<template>
  <AppOverlay
    id="collection-overlay"
    :priority="50"
    labelledby="collection-title"
    :return-focus="props.returnFocus"
    @close="close"
  >
    <div class="collection__panel">
      <header class="collection__head">
        <div>
          <p class="collection__eyebrow">CARD ARCHIVE · 全卡面</p>
          <h2 id="collection-title" class="collection__title">图 鉴 · 卡 库</h2>
        </div>
        <button type="button" class="collection__close" data-testid="collection-close" @click="close">关闭</button>
      </header>

      <div class="collection__controls">
        <div class="collection__modes" role="group" aria-label="分组方式">
          <button
            type="button"
            class="collection__mode"
            :class="{ 'is-active': mode === 'speed' }"
            data-testid="collection-group-speed"
            :aria-pressed="mode === 'speed'"
            @click="mode = 'speed'"
          >
            按速阶
          </button>
          <button
            type="button"
            class="collection__mode"
            :class="{ 'is-active': mode === 'type' }"
            data-testid="collection-group-type"
            :aria-pressed="mode === 'type'"
            @click="mode = 'type'"
          >
            按类型
          </button>
        </div>
        <label class="collection__search">
          <span>搜索</span>
          <input
            v-model="query"
            type="search"
            data-testid="collection-search"
            placeholder="卡名 / 类型 / 描述"
            autocomplete="off"
          />
        </label>
        <p class="collection__count" data-testid="collection-count">已显示 {{ shown }} / {{ total }} 张</p>
      </div>

      <div class="collection__body">
        <p v-if="empty" class="collection__empty" data-testid="collection-empty">没有匹配的卡牌。</p>
        <section
          v-for="group in visibleGroups"
          :key="group.key"
          class="collection__group"
          :data-testid="'collection-group-' + group.key"
        >
          <h3 class="collection__group-title">
            <span>{{ group.label }}</span>
            <small>{{ group.total }} 张</small>
          </h3>
          <ul class="collection__grid" data-testid="collection-grid">
            <li
              v-for="(card, index) in group.cards"
              :key="group.key + '-' + index"
              class="collection-card"
              data-testid="collection-card"
              :data-card-name="card.name"
              :data-speed="card.speed"
              :data-type="card.type"
            >
              <div class="collection-card__face">
                <img
                  v-if="faceFor(card)"
                  :src="faceFor(card) || ''"
                  :alt="card.name + ' 卡面'"
                  loading="lazy"
                  decoding="async"
                />
                <span v-else class="collection-card__missing" aria-hidden="true">无卡面</span>
              </div>
              <div class="collection-card__meta">
                <p class="collection-card__name">{{ card.name }}</p>
                <p class="collection-card__tags">
                  <span>速阶 {{ card.speed }}</span>
                  <span>{{ card.type }}</span>
                </p>
                <p class="collection-card__desc">{{ card.description }}</p>
              </div>
            </li>
          </ul>
        </section>
      </div>

      <footer class="collection__foot">
        <button
          v-if="hasMore"
          type="button"
          class="collection__more"
          data-testid="collection-load-more"
          @click="loadMore"
        >
          继续加载（还有 {{ total - shown }} 张）
        </button>
        <p v-else class="collection__done" data-testid="collection-done">已加载全部 {{ total }} 张卡牌。</p>
      </footer>
    </div>
  </AppOverlay>
</template>

